namespace Htt.IntegrationTests;
public sealed class PeriodCloseTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();
 private readonly DateOnly start=new(2024,7,1);private readonly DateOnly end=new(2025,7,1);
 private async Task<(Guid Year,Guid Period)> Calendar()
 {var y=(Guid)(await S("INSERT INTO accounting.fiscal_years(company_id,label,starts_on,ends_on,created_by)VALUES(@company,@label,@a,@b,@actor)RETURNING id",("company",db.Company),("label",Code()),("a",start),("b",end),("actor",db.Actor)))!;var p=(Guid)(await S("INSERT INTO accounting.periods(company_id,fiscal_year_id,starts_on,ends_on,created_by)VALUES(@company,@y,@a,@b,@actor)RETURNING id",("company",db.Company),("y",y),("a",start),("b",end),("actor",db.Actor)))!;return(y,p);}
 private static Task<HttpResponseMessage> Act(HttpClient c,Guid id,bool year=false,string action="close",long? version=1,bool na=true,string? key=null,AccountingCloseInput? input=null)=>Send(c,HttpMethod.Post,$"/accounting/{(year?"fiscal-years":"periods")}/{id}/{action}",input??new AccountingCloseInput("ref-"+(key??Code()),"Period reviewed",!year&&action=="close"&&na),version,key);
 private Task<JsonElement> Pre(HttpClient c,Guid p,bool na=true)=>Get(c,$"/accounting/periods/{p}/preflight?basNotApplicableConfirmed={na.ToString().ToLowerInvariant()}");
 private async Task<Guid> Post(decimal revenue=100,decimal expense=40,DateOnly? date=null,string kind="PERIOD_TEST")
 {var asset=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@company,@code,'Other asset','ASSET')RETURNING id",("company",db.Company),("code",Code())))!;var rev=(Guid)(await S("SELECT id FROM accounting.accounts WHERE company_id=@company AND code='4000'",("company",db.Company)))!;var exp=(Guid)(await S("SELECT id FROM accounting.accounts WHERE company_id=@company AND kind='EXPENSE' ORDER BY code LIMIT 1",("company",db.Company)))!;var d=date??start;var doc=(Guid)(await S("INSERT INTO platform.documents(company_id,document_type,business_date,created_by)VALUES(@company,'PERIOD_TEST',@date,@actor)RETURNING id",("company",db.Company),("date",d),("actor",db.Actor)))!;var lines=new List<object>();if(revenue>0){lines.Add(new{accountId=asset,debit=revenue,credit=0m});lines.Add(new{accountId=rev,debit=0m,credit=revenue});}if(expense>0){lines.Add(new{accountId=exp,debit=expense,credit=0m});lines.Add(new{accountId=asset,debit=0m,credit=expense});}await using var s=await db.SessionAsync();await Sql.RowsAsync(s,"SELECT accounting.post_journal(@doc,1,@kind,@date,'Period test',@lines::jsonb)",default,("doc",doc),("kind",kind),("date",d),("lines",JsonSerializer.Serialize(lines)));await s.Transaction.CommitAsync();return doc;}
 [Fact]public async Task Empty_month_close_records_evidence_and_reopens_without_journal()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();var p=await Pre(c,x.Period);Assert.Equal("READY",p.GetProperty("status").GetString());var a=await Expect(await Act(c,x.Period),HttpStatusCode.OK);Assert.Equal("CLOSED",a.GetProperty("entity").GetProperty("state").GetString());await Expect(await Act(c,x.Period,action:"reopen",version:2),HttpStatusCode.OK);var h=await Get(c,$"/accounting/periods/{x.Period}/history");Assert.Equal(2,h.GetProperty("events").GetArrayLength());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company)));}
 [Theory][InlineData(100,40,60)][InlineData(20,50,-30)][InlineData(70,70,0)]public async Task Annual_closing_and_reversal_preserve_profit_and_equity(decimal revenue,decimal expense,decimal profit)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();await Post(revenue,expense);await Expect(await Act(c,x.Period),HttpStatusCode.OK);var pre=await Get(c,$"/accounting/fiscal-years/{x.Year}/preflight");Assert.Equal("READY",pre.GetProperty("status").GetString());Assert.Equal(profit,D(pre.GetProperty("profit")));await Expect(await Act(c,x.Year,true),HttpStatusCode.OK);var pl=await Get(c,$"/accounting/reports/profit-and-loss?from={start:yyyy-MM-dd}&to={end:yyyy-MM-dd}");Assert.Equal(profit,D(pl.GetProperty("totals").GetProperty("netProfit")));var bs=await Get(c,$"/accounting/reports/balance-sheet?asOf={end.AddDays(-1):yyyy-MM-dd}");Assert.Equal(0,D(bs.GetProperty("totals").GetProperty("difference")));Assert.Equal(0,D(bs.GetProperty("totals").GetProperty("currentYearEarnings")));Assert.Equal(profit,D(bs.GetProperty("totals").GetProperty("postedEquity")));await Expect(await Act(c,x.Year,true,"reopen",2),HttpStatusCode.OK);Assert.Equal(0m,await S("SELECT coalesce(sum(l.debit-l.credit),0)FROM accounting.journal_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE a.company_id=@company AND a.code='3100'",("company",db.Company)));await Expect(await Act(c,x.Period,action:"reopen",version:2),HttpStatusCode.OK);await Post(10,0);await Expect(await Act(c,x.Period,version:3),HttpStatusCode.OK);await Expect(await Act(c,x.Year,true,version:3),HttpStatusCode.OK);Assert.Equal(2L,await S("SELECT count(*)FROM accounting.year_end_closings WHERE company_id=@company",("company",db.Company)));}

 private async Task<Guid> Bas(HttpClient c,DateOnly? a=null,DateOnly? b=null,string basis="NON_CASH")=>Id(await Expect(await Send(c,HttpMethod.Post,"/accounting/bas-periods",new BasPeriodInput(Code(),a??start,b??end,"CUSTOM",basis,"SIMPLER",true)),HttpStatusCode.Created));
 private static Task<HttpResponseMessage> BasAct(HttpClient c,Guid id,string action="finalize",long version=1)=>Send(c,HttpMethod.Post,$"/accounting/bas-periods/{id}/{action}",new BasActionInput(Code(),"Tax reviewed"),version);
 private async Task<(Guid Year,Guid First,Guid Second)> Split()
 {var x=await Calendar();var middle=start.AddMonths(1);await S("UPDATE accounting.periods SET ends_on=@mid WHERE company_id=@company AND id=@id",("company",db.Company),("mid",middle),("id",x.Period));var second=(Guid)(await S("INSERT INTO accounting.periods(company_id,fiscal_year_id,starts_on,ends_on,created_by)VALUES(@company,@y,@a,@b,@actor)RETURNING id",("company",db.Company),("y",x.Year),("a",middle),("b",end),("actor",db.Actor)))!;return(x.Year,x.Period,second);}
 [Fact] public async Task Zero_activity_year_has_evidence_but_no_empty_posting_batch()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();await Expect(await Act(c,x.Period),HttpStatusCode.OK);await Expect(await Act(c,x.Year,true),HttpStatusCode.OK);await Expect(await Act(c,x.Year,true,"reopen",2),HttpStatusCode.OK);Assert.Equal(0L,await S("SELECT count(*)FROM accounting.posting_batches WHERE company_id=@company",("company",db.Company)));var history=await Get(c,$"/accounting/fiscal-years/{x.Year}/history");Assert.Single(history.GetProperty("closings").EnumerateArray());Assert.Single(history.GetProperty("reversals").EnumerateArray());}
 [Theory][InlineData(false)][InlineData(true)]public async Task Idempotent_close_replay_returns_identical_evidence(bool year)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();if(year)await Expect(await Act(c,x.Period),HttpStatusCode.OK);var id=year?x.Year:x.Period;var key=Code();var a=await Expect(await Act(c,id,year,key:key),HttpStatusCode.OK);var b=await Expect(await Act(c,id,year,key:key),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,b));Assert.Equal(1L,await S("SELECT count(*)FROM accounting."+(year?"year_end_closings":"period_close_snapshots")+" WHERE company_id=@company",("company",db.Company)));await Expect(await Act(c,id,year,key:key,input:new AccountingCloseInput("different","Changed",!year)),HttpStatusCode.Conflict);}
 [Theory][InlineData(false)][InlineData(true)]public async Task Two_independent_close_requests_only_commit_once(bool year)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();if(year)await Expect(await Act(c,x.Period),HttpStatusCode.OK);var id=year?x.Year:x.Period;var responses=await Task.WhenAll(Act(c,id,year),Act(c,id,year));Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);}
 [Theory][InlineData(false)][InlineData(true)]public async Task Same_idempotency_key_concurrent_calls_share_result(bool year)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();if(year)await Expect(await Act(c,x.Period),HttpStatusCode.OK);var key=Code();var id=year?x.Year:x.Period;var all=await Task.WhenAll(Act(c,id,year,key:key),Act(c,id,year,key:key));var a=await Expect(all[0],HttpStatusCode.OK);var b=await Expect(all[1],HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,b));}
 [Theory][InlineData(false)][InlineData(true)]public async Task Reopen_retry_does_not_duplicate_reversal_or_event(bool year)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();await Post();await Expect(await Act(c,x.Period),HttpStatusCode.OK);if(year)await Expect(await Act(c,x.Year,true),HttpStatusCode.OK);var key=Code();var id=year?x.Year:x.Period;var a=await Expect(await Act(c,id,year,"reopen",2,key:key),HttpStatusCode.OK);var b=await Expect(await Act(c,id,year,"reopen",2,key:key),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,b));Assert.Equal(1L,await S("SELECT count(*)FROM accounting."+(year?"year_end_reversals":"period_close_events")+" WHERE company_id=@company"+(year?"":" AND action='REOPENED'"),("company",db.Company)));}
 [Theory][InlineData(null,428)][InlineData(99L,409)]public async Task Current_period_version_required(long? v,int code)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();await Expect(await Act(c,x.Period,version:v),(HttpStatusCode)code);Assert.Equal(0L,await S("SELECT count(*)FROM accounting.period_close_snapshots WHERE company_id=@company",("company",db.Company)));}
