 [Theory][InlineData("accounting.periods.close")][InlineData("accounting.periods.read")][InlineData("accounting.bas.read")][InlineData("accounting.ledger.read")][InlineData("accounting.gst.read")][InlineData("purchase.input_gst.read")][InlineData("accounting.reconciliation.read")]
