 [Fact]public async Task Historical_calendars_can_be_created_idempotently_with_twelve_months()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var input=new FiscalYearInput("FY2025",start,end);var key=Code();var a=await Expect(await Send(c,HttpMethod.Post,"/accounting/fiscal-years",input,key:key),HttpStatusCode.Created);var b=await Expect(await Send(c,HttpMethod.Post,"/accounting/fiscal-years",input,key:key),HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,b));var p=await Get(c,$"/accounting/periods?fiscalYearId={Id(a)}");Assert.Equal(12,p.GetProperty("items").GetArrayLength());await Expect(await Send(c,HttpMethod.Post,"/accounting/fiscal-years",input),HttpStatusCode.Conflict);}
