 [Fact]public async Task Sequential_close_and_reverse_order_reopen_are_enforced()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Split();Assert.Contains("EARLIER_PERIODS_OPEN",(await Pre(c,x.Second)).GetProperty("issues").EnumerateArray().Select(v=>v.GetString()));await Expect(await Act(c,x.Second),HttpStatusCode.Conflict);await Expect(await Act(c,x.First,version:2),HttpStatusCode.OK);await Expect(await Act(c,x.Second),HttpStatusCode.OK);await Expect(await Act(c,x.First,action:"reopen",version:3),HttpStatusCode.Conflict);await Expect(await Act(c,x.Second,action:"reopen",version:2),HttpStatusCode.OK);await Expect(await Act(c,x.First,action:"reopen",version:3),HttpStatusCode.OK);}
 [Fact]public async Task Unended_period_and_year_cannot_close()
