 private async Task<SalesData> HistoricalStock(HttpClient c)
 {var d=await Setup(db,c,10);await using var source=NpgsqlDataSource.Create(db.Owner);await using var session=new CompanySession(source);await session.BeginAsync(db.Company,db.Actor,"historic-stock-fixture",default);var id=Guid.NewGuid();await Sql.RowsAsync(session,"""
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(@id,@company,'STOCK_VALUATION',@number,@date,'CONFIRMED',@actor);
 INSERT INTO inventory.valuation_openings(id,company_id,stock_balance_id,quantity,value,reference,created_by)SELECT @id,@company,id,on_hand,100,@number,@actor FROM inventory.stock_balances WHERE company_id=@company AND warehouse_id=@w AND product_id=@p;
 INSERT INTO inventory.stock_values(company_id,stock_balance_id,value,opening_document_id)SELECT @company,id,100,@id FROM inventory.stock_balances WHERE company_id=@company AND warehouse_id=@w AND product_id=@p;
 SELECT accounting.post_journal(@id,1,'STOCK_OPENING',@date,'Historical opening',jsonb_build_array(jsonb_build_object('accountId',(SELECT account_id FROM accounting.account_mappings WHERE company_id=@company AND purpose='INVENTORY'),'debit',100),jsonb_build_object('accountId',(SELECT account_id FROM accounting.account_mappings WHERE company_id=@company AND purpose='OPENING_EQUITY'),'credit',100)));
 UPDATE platform.documents SET state='POSTED' WHERE company_id=@company AND id=@id;
 """,default,("id",id),("company",db.Company),("number",Code()),("date",start),("actor",db.Actor),("w",d.Warehouse),("p",d.Product));await session.Transaction.CommitAsync();return d;}
