 [Theory][InlineData(false)][InlineData(true)]public async Task Late_audit_failure_rolls_back_all_close_effects_and_original_key_retries(bool year)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Calendar();await Post();if(year)await Expect(await Act(c,x.Period),HttpStatusCode.OK);var id=year?x.Year:x.Period;var key=Code();var action=year?"accounting.year_close":"accounting.period_close";await S($"CREATE FUNCTION accounting.test_period_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'::uuid AND NEW.action='{action}'THEN RAISE EXCEPTION 'Injected audit failure' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_period_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_period_failure()");try{await Expect(await Act(c,id,year,key:key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM accounting."+(year?"year_end_closings":"period_close_snapshots")+" WHERE company_id=@company",("company",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company)));}finally{await S("DROP TRIGGER test_period_failure ON platform.audit_events;DROP FUNCTION accounting.test_period_failure()");}await Expect(await Act(c,id,year,key:key),HttpStatusCode.OK);}
